import{c as t,Q as n,j as o,m as a}from"./chunks/framework.BqPkuuVc.js";const u=JSON.parse('{"title":"The event dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"user/running-the-event/dashboard.md","filePath":"user/running-the-event/dashboard.md"}'),r={name:"user/running-the-event/dashboard.md"};function s(i,e,d,h,l,g){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="the-event-dashboard" tabindex="-1">The event dashboard <a class="header-anchor" href="#the-event-dashboard" aria-label="Permalink to &quot;The event dashboard&quot;">​</a></h1><p><strong>Audience:</strong> Timing operators watching and running the event on the day.</p><p>The dashboard is your home base while an event runs — open it on the operator&#39;s screen and leave it up. It&#39;s the landing page for an event and gives you, at a glance, the event&#39;s status, how many competitors are still out, the health of your radio network, and one-click access to the jobs you do most. This page explains every card and indicator, and what to do when one changes colour.</p><h2 id="the-top-bar-status-and-event-controls" tabindex="-1">The top bar: status and event controls <a class="header-anchor" href="#the-top-bar-status-and-event-controls" aria-label="Permalink to &quot;The top bar: status and event controls&quot;">​</a></h2><p>The strip across the top of every event page (not just the dashboard) carries the event&#39;s lifecycle:</p><ul><li><strong>Status chip</strong> — the event&#39;s current state, also echoed as a coloured stripe down the left of the header card below: <ul><li><strong>Setup mode</strong> — not started yet (you&#39;re still preparing it)</li><li><strong>Event in progress</strong> — live; the chip pulses</li><li><strong>Event stopping</strong> / <strong>Event interrupted</strong> — paused or interrupted mid-run</li><li><strong>Event completed</strong> — finished</li><li><strong>Event abandoned</strong> — ended without completing</li></ul></li><li><strong>Event clock</strong> — a running event time, shown while the event is in progress.</li><li><strong>The primary button</strong> changes with the state: <strong>Start event</strong> (in setup), <strong>Finish event</strong> (while live), or <strong>Resume event</strong> (for an interrupted or abandoned event, alongside <strong>Mark finished</strong>). Once an event is finished there&#39;s nothing left to do, so <strong>Close</strong> becomes the primary button and <strong>Restart event</strong> sits alongside it as a quiet, secondary option.</li><li><strong>Replay</strong> controls appear when an event has captured data to replay; this is a testing/training tool rather than something you use live.</li></ul><h3 id="restarting-an-event-you-ve-already-finished" tabindex="-1">Restarting an event you&#39;ve already finished <a class="header-anchor" href="#restarting-an-event-you-ve-already-finished" aria-label="Permalink to &quot;Restarting an event you&#39;ve already finished&quot;">​</a></h3><p>Finishing an event isn&#39;t final. If a competitor walks out of the forest after you&#39;ve closed the event off, open the event and click <strong>Restart event</strong> in the app bar. Manager warns you first, then takes the event live again so you can download the card, fix the result, and finish it a second time.</p><p>This works however long ago the event was — you can restart yesterday&#39;s event tomorrow morning. Reading a card late doesn&#39;t distort anything: the card holds the times of day the competitor actually punched, so their result comes out the same as it would have on the day.</p><p>Two things to know:</p><ul><li>Only one event can be live at a time. If another event is running, finish it first.</li><li>Remember to click <strong>Finish event</strong> again when you&#39;re done, so the event goes back to being finished.</li></ul><blockquote><p><strong>Note:</strong> An event that never ran and whose date has passed is the one case Manager won&#39;t start — there&#39;s no <strong>Start event</strong> button for it. Change the date first (<strong>Edit event details</strong>), then start it.</p></blockquote><h2 id="the-event-header" tabindex="-1">The event header <a class="header-anchor" href="#the-event-header" aria-label="Permalink to &quot;The event header&quot;">​</a></h2><p>The card at the top of the dashboard identifies the event: its <strong>name</strong>, <strong>date</strong>, and a row of attributes — event type (individual / relay / team), competition level, discipline, and whether it&#39;s an individual or mass start — plus an <strong>Eventor</strong> marker if it was imported from Eventor. The left border is colour-coded to the status.</p><p>The <strong>cog</strong> button (top-right of the card) opens <strong>Edit event details</strong>, where you change the name, date, radio-control settings, mass start, splits printing, hire items, and extensions. See <a href="./../event-setup/create-event#editing-event-details">Editing event details</a>.</p><h2 id="always-on-cards" tabindex="-1">Always-on cards <a class="header-anchor" href="#always-on-cards" aria-label="Permalink to &quot;Always-on cards&quot;">​</a></h2><p>Three cards are always present.</p><h3 id="event-data" tabindex="-1">Event Data <a class="header-anchor" href="#event-data" aria-label="Permalink to &quot;Event Data&quot;">​</a></h3><p>A count of everything you&#39;ve set up — <strong>controls, courses, classes, competitors</strong> (or <strong>teams</strong> for a relay), and <strong>clubs</strong>. It&#39;s your at-a-glance check that setup is complete: a zero where you expect a number means something hasn&#39;t been imported or created yet. <strong>Click any count</strong> to jump straight to that list, and use <strong>Import</strong> (top-right) to bring in more data. See <a href="./../event-setup/import-event-data">Importing event data</a>.</p><h3 id="competitors" tabindex="-1">Competitors <a class="header-anchor" href="#competitors" aria-label="Permalink to &quot;Competitors&quot;">​</a></h3><p>The headline numbers for the race in progress:</p><ul><li><strong>Total</strong> — everyone entered.</li><li><strong>Started</strong> — how many have started.</li><li><strong>On Course</strong> — how many Manager believes are <strong>still out on the course</strong>. This is your safety number.</li><li><strong>Pending</strong> — runners who have crossed a <strong>radio finish</strong> but whose <strong>card hasn&#39;t been downloaded yet</strong>, so their result is still <em>preliminary</em>. They sit between On Course and Finished. (Only shown once radio punches are arriving.)</li><li><strong>Finished</strong> — competitors with a downloaded card and an authoritative result.</li></ul><p>A live mini-chart below the numbers tracks the On Course count over time, so you can see the field flow out and back.</p><p><strong>On Course</strong> and <strong>Pending</strong> are clickable — they&#39;re drawn as coloured, raised buttons whenever they have something to show. Clicking opens the list behind each. At zero they look like the plain counts either side of them, so a coloured button always means there&#39;s a list to open.</p><blockquote><p><strong>Safety — is everyone back?</strong> <strong>On Course</strong> is the number that matters at the end of the day. While it&#39;s above zero, click it to open the <strong>On Course</strong> list and work through who&#39;s still out, who has finished but not downloaded, and who never started. The full procedure — including reading start/finish station memory and clearing no-shows — is on its own page: <strong><a href="./safety-check">Safety check: accounting for everyone</a></strong>. Click <strong>Pending</strong> to see the preliminary-result runners due at the download desk. For every <em>other</em> place the same picture surfaces, see <a href="./who-is-still-on-course">Seeing who is still on course</a>.</p></blockquote><h2 id="cards-that-appear-when-relevant" tabindex="-1">Cards that appear when relevant <a class="header-anchor" href="#cards-that-appear-when-relevant" aria-label="Permalink to &quot;Cards that appear when relevant&quot;">​</a></h2><p>The rest of the dashboard adapts to the event&#39;s state and which features are switched on, so you only see what&#39;s useful right now:</p><table tabindex="0"><thead><tr><th>Card</th><th>What it shows</th><th>Appears when</th></tr></thead><tbody><tr><td><strong>Quick Competitor Actions</strong></td><td>Search and open a competitor; change their card number or class; <strong>+</strong> to add a competitor</td><td>The event is being set up or run</td></tr><tr><td><strong>Download Card</strong></td><td>Reader connection and live card downloads</td><td>The event is in progress (and not replaying)</td></tr><tr><td><strong>Radio Controls</strong></td><td>Each radio control&#39;s health — recent punch activity, last-heard time, battery, and signal</td><td>The event uses meshO radios</td></tr><tr><td><strong>Radio Punch Forwarding</strong></td><td>Outbound forwarding status — <strong>Active</strong>/<strong>Disabled</strong>, with <strong>Sent</strong> and <strong>Queued</strong> counts</td><td>Punch forwarding is switched on</td></tr><tr><td><strong>SIRAP Punch Listening</strong></td><td>Inbound SIRAP punch source — <strong>Listening</strong>/<strong>Stopped</strong>, with a <strong>Received</strong> count that restarts when an event starts accepting punches</td><td>The event accepts SIRAP punches</td></tr><tr><td><strong>Spectators</strong></td><td>How many people are <strong>watching now</strong> on the live screens</td><td>The event is in progress</td></tr><tr><td><strong>Extension tiles</strong></td><td>Whatever an installed extension contributes</td><td>An enabled extension provides a dashboard tile</td></tr></tbody></table><p>A few of these have their own pages:</p><ul><li><strong>Quick Competitor Actions</strong> is the fastest way to fix a single competitor&#39;s card or class without leaving the dashboard — for deeper edits, open them in the <a href="./../event-setup/competitors-clubs-teams">Competitors list</a>.</li><li><strong>Download Card</strong> is a compact version of the full <a href="./card-download">Downloading cards</a> station — and, as that page explains, downloads register from anywhere, so the tile updates even when you&#39;re elsewhere.</li><li><strong>Radio Controls</strong> is your radio-network health panel. Low battery or a control that&#39;s gone quiet shows here first; for setup and recovery see <a href="./connecting-prime-and-radios">Connecting meshO Prime and radios</a> and <a href="./radio-punches">Radio punches</a>.</li><li><strong>Extension tiles</strong> come from add-ons you&#39;ve installed — see <a href="./../advanced/installing-extensions">Installing extensions</a>.</li></ul><h2 id="reading-the-colours" tabindex="-1">Reading the colours <a class="header-anchor" href="#reading-the-colours" aria-label="Permalink to &quot;Reading the colours&quot;">​</a></h2><p>Colour is used consistently across the dashboard so problems catch your eye:</p><ul><li><strong>Green</strong> — healthy or live: an in-progress event, a connected reader (<strong>Listening</strong>), forwarding that&#39;s <strong>Active</strong>, controls reporting in normally.</li><li><strong>Orange / yellow</strong> — attention, not yet a failure: punches <strong>Queued</strong> for forwarding, a control on <strong>low battery</strong> or weak signal, an interrupted event.</li><li><strong>Red / grey</strong> — stopped or finished: an <strong>abandoned</strong> (red) or <strong>completed</strong> (grey) event, a critical battery, a control that hasn&#39;t been heard from.</li></ul><p>When the <strong>Radio Controls</strong> card flags low batteries or a silent control, treat it as an early warning and check that unit before it costs you punches.</p><h2 id="what-isn-t-on-the-dashboard" tabindex="-1">What isn&#39;t on the dashboard <a class="header-anchor" href="#what-isn-t-on-the-dashboard" aria-label="Permalink to &quot;What isn&#39;t on the dashboard&quot;">​</a></h2><p>A couple of common jobs live elsewhere, by design:</p><ul><li><strong>Marking competitors DNS in bulk</strong> is done from the competitor lists (the dedicated <em>Set DNS</em> dialog), not here. See <a href="./safety-check">Safety check</a>.</li><li><strong>Re-checking a download, overriding a status, or editing punches</strong> is done from the <a href="./card-download">Downloading cards</a> page or the competitor&#39;s record — see <a href="./resolving-issues">Resolving issues on the day</a>.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./safety-check">Safety check: accounting for everyone</a> — working the On Course list</li><li><a href="./who-is-still-on-course">Seeing who is still on course</a> — every place the on-course picture surfaces</li><li><a href="./card-download">Downloading cards</a> — the Download Card station in full</li><li><a href="./connecting-prime-and-radios">Connecting meshO Prime and radios</a> — the radio network behind the Radio Controls card</li><li><a href="./radio-punches">Radio punches</a> — punches arriving live from the field</li><li><a href="./resolving-issues">Resolving issues on the day</a> — fixing competitors and results</li><li><a href="./../event-setup/create-event#editing-event-details">Creating an event</a> — the event lifecycle and Edit event details</li></ul>',39)])])}const p=t(r,[["render",s]]);export{u as __pageData,p as default};
